#[test]
#[cfg(not(feature = "native-standalone"))]
fn standalone_tree_cpp_baseline_reports_native_feature_disabled_by_default() {
    let (mut tree, root, constraints) = measured_flex_row_tree();

    let error = CppStarlightEngine::new()
        .layout(&mut tree, root, constraints)
        .expect_err("native C++ backend should be explicitly enabled");

    assert_eq!(error, CppBaselineError::NativeFeatureDisabled);
}

