#[test]
#[cfg(feature = "native-standalone")]
fn standalone_owned_tree_matches_cpp_for_mutation_relayout_after_clean_layout() {
    let (tree, root, constraints, ids) = mutation_relayout_after_clean_layout_tree();

    run_mutating_standalone_head_to_head(tree, root, constraints, |tree| {
        tree.remove_child(root, ids.removed)
            .expect("remove child before relayout");
        tree.set_measured_size(ids.resized, Some(Size::new(24.0, 13.0)))
            .expect("update measured child before relayout");
        tree.set_margin(ids.resized, StandaloneEdge::Right, Length::points(2.0))
            .expect("set measured child relayout margin");
        tree.insert_child_before(root, ids.inserted, ids.trailing)
            .expect("insert new child before trailing child");
        tree.set_gap(root, StandaloneGap::Column, Length::points(3.0))
            .expect("update root column gap before relayout");
    })
    .expect("mutation relayout parity");
}

