#[test]
#[cfg(feature = "native-standalone")]
#[ignore = "current standalone C API/C++ path uses the content-box padding edge for absolute grid auto lines when tracks overflow; Rust follows W3C sections 5.3 and 9.1 and uses the scrollable overflow padding edge"]
fn standalone_owned_tree_records_cpp_gap_for_grid_scrollable_overflow_abspos_auto_lines() {
    for direction in layout_direction_variants() {
        let (case_name, tree, root, constraints) =
            grid_scrollable_overflow_abspos_auto_lines_tree(direction);
        let error = run_raw_standalone_head_to_head(tree, root, constraints)
            .expect_err(&format!("{case_name} should record a standalone C++ gap"));
        assert!(
            matches!(
                error,
                ParityError::LayoutMismatch {
                    node,
                    field: LayoutField::Width | LayoutField::OffsetX,
                    ..
                } if node != root
            ),
            "{case_name} should differ on the absolute child scrollable auto-line geometry, got {error:?}"
        );
    }
}

