#[test]
#[cfg(feature = "native-standalone")]
fn standalone_owned_tree_matches_cpp_for_relative_parent_alignment_precedence() {
    {
        let mut tree = StandaloneTree::new();
        let root = tree.create_default_node();
        tree.set_display(root, Display::Relative)
            .expect("set root display");
        tree.set_width(root, Length::points(100.0))
            .expect("set root width");
        tree.set_height(root, Length::points(40.0))
            .expect("set root height");

        let anchor = tree.create_default_measured_node(Size::new(20.0, 10.0));
        tree.set_relative_id(anchor, 10)
            .expect("set anchor relative id");

        let follower = tree.create_default_measured_node(Size::new(5.0, 7.0));
        tree.set_relative_align_left(follower, RELATIVE_ALIGN_PARENT)
            .expect("set follower parent-left alignment");
        tree.set_relative_align_top(follower, RELATIVE_ALIGN_PARENT)
            .expect("set follower parent-top alignment");
        tree.set_relative_right_of(follower, 10)
            .expect("set follower right-of dependency");
        tree.set_relative_bottom_of(follower, 10)
            .expect("set follower bottom-of dependency");

        tree.append_child(root, follower).expect("append follower");
        tree.append_child(root, anchor).expect("append anchor");

        run_standalone_head_to_head(tree, root, Constraints::definite(100.0, 40.0))
            .expect("relative parent-start alignment precedence parity");
    }

    {
        let mut tree = StandaloneTree::new();
        let root = tree.create_default_node();
        tree.set_display(root, Display::Relative)
            .expect("set root display");
        tree.set_width(root, Length::points(100.0))
            .expect("set root width");
        tree.set_height(root, Length::points(40.0))
            .expect("set root height");

        let anchor = tree.create_default_measured_node(Size::new(20.0, 10.0));
        tree.set_relative_id(anchor, 10)
            .expect("set anchor relative id");

        let follower = tree.create_default_measured_node(Size::new(5.0, 7.0));
        tree.set_relative_align_right(follower, RELATIVE_ALIGN_PARENT)
            .expect("set follower parent-right alignment");
        tree.set_relative_align_bottom(follower, RELATIVE_ALIGN_PARENT)
            .expect("set follower parent-bottom alignment");
        tree.set_relative_left_of(follower, 10)
            .expect("set follower left-of dependency");
        tree.set_relative_top_of(follower, 10)
            .expect("set follower top-of dependency");

        tree.append_child(root, follower).expect("append follower");
        tree.append_child(root, anchor).expect("append anchor");

        run_standalone_head_to_head(tree, root, Constraints::definite(100.0, 40.0))
            .expect("relative parent-end alignment precedence parity");
    }
}

