#[test]
#[cfg(feature = "native-standalone")]
fn standalone_owned_tree_matches_cpp_for_relative_missing_align_left_falls_back_to_right_of_with_root_padding_border(
) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_box_sizing(root, BoxSizing::ContentBox)
        .expect("set root box sizing");
    tree.set_width(root, Length::points(150.0))
        .expect("set root width");
    tree.set_height(root, Length::points(90.0))
        .expect("set root height");
    tree.set_padding(root, StandaloneEdge::Horizontal, Length::points(5.0))
        .expect("set root horizontal padding");
    tree.set_padding(root, StandaloneEdge::Vertical, Length::points(4.0))
        .expect("set root vertical padding");
    tree.set_border(root, StandaloneEdge::All, 1.0)
        .expect("set root border");

    let anchor = tree.create_default_measured_node(Size::new(32.0, 18.0));
    tree.set_display(anchor, Display::Block)
        .expect("set anchor display");
    tree.set_relative_id(anchor, 10)
        .expect("set anchor relative id");
    tree.set_relative_align_right(anchor, RELATIVE_ALIGN_PARENT)
        .expect("set anchor parent-right alignment");
    tree.set_relative_align_top(anchor, RELATIVE_ALIGN_PARENT)
        .expect("set anchor parent-top alignment");

    let child = tree.create_default_measured_node(Size::new(22.0, 14.0));
    tree.set_display(child, Display::Block)
        .expect("set child display");
    tree.set_relative_align_left(child, 999)
        .expect("set child missing align-left");
    tree.set_relative_right_of(child, 10)
        .expect("set child right-of fallback");
    tree.set_relative_bottom_of(child, 10)
        .expect("set child bottom-of anchor");
    tree.set_margin(child, StandaloneEdge::Left, Length::calc(3.0, 4.0))
        .expect("set child left margin");
    tree.set_margin(child, StandaloneEdge::Top, Length::calc(2.0, 5.0))
        .expect("set child top margin");

    tree.append_child(root, child).expect("append child");
    tree.append_child(root, anchor).expect("append anchor");

    run_standalone_head_to_head(tree, root, Constraints::definite(162.0, 100.0))
        .expect("relative missing align-left fallback with root padding/border parity");
}

