#[test]
#[cfg(feature = "native-standalone")]
fn standalone_owned_tree_matches_cpp_for_relative_ordered_duplicate_id_right_of_skips_display_none_with_padding_border(
) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_box_sizing(root, BoxSizing::ContentBox)
        .expect("set root box sizing");
    tree.set_width(root, Length::points(150.0))
        .expect("set root width");
    tree.set_height(root, Length::points(90.0))
        .expect("set root height");
    tree.set_padding(root, StandaloneEdge::Left, Length::points(6.0))
        .expect("set root left padding");
    tree.set_padding(root, StandaloneEdge::Right, Length::points(4.0))
        .expect("set root right padding");
    tree.set_border(root, StandaloneEdge::Left, 1.0)
        .expect("set root left border");
    tree.set_border(root, StandaloneEdge::Right, 2.0)
        .expect("set root right border");

    let first_anchor = tree.create_default_measured_node(Size::new(28.0, 16.0));
    tree.set_relative_id(first_anchor, 10)
        .expect("set first anchor id");
    tree.set_order(first_anchor, 1)
        .expect("set first anchor order");

    let hidden_anchor = tree.create_default_node();
    tree.set_display(hidden_anchor, Display::None)
        .expect("set hidden anchor display");
    tree.set_width(hidden_anchor, Length::points(80.0))
        .expect("set hidden anchor width");
    tree.set_height(hidden_anchor, Length::points(30.0))
        .expect("set hidden anchor height");
    tree.set_relative_id(hidden_anchor, 10)
        .expect("set hidden anchor id");
    tree.set_order(hidden_anchor, 4)
        .expect("set hidden anchor order");

    let last_visible_anchor = tree.create_default_measured_node(Size::new(46.0, 18.0));
    tree.set_relative_id(last_visible_anchor, 10)
        .expect("set last visible anchor id");
    tree.set_order(last_visible_anchor, 3)
        .expect("set last visible anchor order");
    tree.set_relative_align_left(last_visible_anchor, RELATIVE_ALIGN_PARENT)
        .expect("set last visible parent-left alignment");

    let follower = tree.create_default_measured_node(Size::new(20.0, 12.0));
    tree.set_relative_right_of(follower, 10)
        .expect("set follower right-of duplicate id");
    tree.set_margin(follower, StandaloneEdge::Left, Length::points(5.0))
        .expect("set follower left margin");
    tree.set_order(follower, 5).expect("set follower order");

    tree.append_child(root, hidden_anchor)
        .expect("append hidden anchor");
    tree.append_child(root, follower).expect("append follower");
    tree.append_child(root, first_anchor)
        .expect("append first anchor");
    tree.append_child(root, last_visible_anchor)
        .expect("append last visible anchor");

    run_standalone_head_to_head(tree, root, Constraints::definite(150.0, 90.0)).expect(
        "relative ordered duplicate id right-of skips display-none with padding/border parity",
    );
}

