#[test]
#[cfg(feature = "native-standalone")]
fn standalone_owned_tree_matches_cpp_for_relative_two_pass_wrap_content_remeasure() {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_padding(root, StandaloneEdge::Left, Length::points(3.0))
        .expect("set root left padding");
    tree.set_padding(root, StandaloneEdge::Right, Length::points(4.0))
        .expect("set root right padding");
    tree.set_padding(root, StandaloneEdge::Top, Length::points(5.0))
        .expect("set root top padding");
    tree.set_padding(root, StandaloneEdge::Bottom, Length::points(2.0))
        .expect("set root bottom padding");

    let anchor = tree.create_default_measured_node(Size::new(20.0, 10.0));
    tree.set_relative_id(anchor, 1)
        .expect("set anchor relative id");
    tree.set_relative_align_left(anchor, RELATIVE_ALIGN_PARENT)
        .expect("set anchor parent left");
    tree.set_relative_align_top(anchor, RELATIVE_ALIGN_PARENT)
        .expect("set anchor parent top");
    tree.set_margin(anchor, StandaloneEdge::Left, Length::points(2.0))
        .expect("set anchor left margin");
    tree.set_margin(anchor, StandaloneEdge::Right, Length::points(1.0))
        .expect("set anchor right margin");
    tree.set_margin(anchor, StandaloneEdge::Top, Length::points(3.0))
        .expect("set anchor top margin");

    let dependent = tree.create_default_measured_node(Size::new(16.0, 12.0));
    tree.set_relative_id(dependent, 2)
        .expect("set dependent relative id");
    tree.set_relative_align_left(dependent, 1)
        .expect("set dependent align left");
    tree.set_relative_align_right(dependent, RELATIVE_ALIGN_PARENT)
        .expect("set dependent parent right");
    tree.set_relative_align_top(dependent, 1)
        .expect("set dependent align top");
    tree.set_relative_align_bottom(dependent, RELATIVE_ALIGN_PARENT)
        .expect("set dependent parent bottom");
    tree.set_margin(dependent, StandaloneEdge::Left, Length::points(1.0))
        .expect("set dependent left margin");
    tree.set_margin(dependent, StandaloneEdge::Right, Length::points(2.0))
        .expect("set dependent right margin");
    tree.set_margin(dependent, StandaloneEdge::Top, Length::points(1.0))
        .expect("set dependent top margin");
    tree.set_margin(dependent, StandaloneEdge::Bottom, Length::points(3.0))
        .expect("set dependent bottom margin");

    let follower = tree.create_default_measured_node(Size::new(9.0, 7.0));
    tree.set_relative_left_of(follower, 2)
        .expect("set follower before dependent");
    tree.set_relative_top_of(follower, 2)
        .expect("set follower above dependent");

    tree.append_child(root, anchor).expect("append anchor");
    tree.append_child(root, dependent)
        .expect("append dependent");
    tree.append_child(root, follower).expect("append follower");

    run_standalone_head_to_head(tree, root, Constraints::indefinite())
        .expect("relative two-pass wrap-content remeasure parity");
}

