    tree.set_relative_id(first_anchor, 300)
        .expect("set first anchor id");
    tree.set_order(first_anchor, 1)
        .expect("set first anchor order");

    let visible_anchor = tree.create_default_measured_node(Size::new(42.0, 14.0));
    tree.set_relative_id(visible_anchor, 300)
        .expect("set visible anchor id");
    tree.set_order(visible_anchor, 3)
