fn standalone_owned_tree_matches_cpp_for_relative_center_suppressed_by_sibling_vertical_edges_with_padding_border(
) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_box_sizing(root, BoxSizing::ContentBox)
        .expect("set root box sizing");
    tree.set_width(root, Length::points(112.0))
        .expect("set root width");
    tree.set_height(root, Length::points(202.0))
        .expect("set root height");
    tree.set_padding(root, StandaloneEdge::Left, Length::points(4.0))
        .expect("set root left padding");
    tree.set_padding(root, StandaloneEdge::Top, Length::points(6.0))
        .expect("set root top padding");
    tree.set_padding(root, StandaloneEdge::Bottom, Length::points(8.0))
        .expect("set root bottom padding");
    tree.set_border(root, StandaloneEdge::Left, 1.0)
        .expect("set root left border");
    tree.set_border(root, StandaloneEdge::Top, 1.0)
        .expect("set root top border");
    tree.set_border(root, StandaloneEdge::Bottom, 2.0)
        .expect("set root bottom border");

    let top_anchor = tree.create_default_measured_node(Size::new(20.0, 29.0));
    tree.set_relative_id(top_anchor, 10)
        .expect("set top anchor id");
    tree.set_relative_align_top(top_anchor, RELATIVE_ALIGN_PARENT)
        .expect("set top anchor parent-top alignment");

    let bottom_anchor = tree.create_default_measured_node(Size::new(20.0, 38.0));
    tree.set_relative_id(bottom_anchor, 20)
        .expect("set bottom anchor id");
    tree.set_relative_align_bottom(bottom_anchor, RELATIVE_ALIGN_PARENT)
        .expect("set bottom anchor parent-bottom alignment");

    let child = tree.create_default_node();
    tree.set_display(child, Display::Block)
        .expect("set child display");
    tree.set_width(child, Length::points(17.0))
        .expect("set child width");
    tree.set_margin(child, StandaloneEdge::Top, Length::percent(4.0))
        .expect("set child top percent margin");
    tree.set_margin(child, StandaloneEdge::Bottom, Length::percent(6.0))
        .expect("set child bottom percent margin");
    tree.set_margin(child, StandaloneEdge::Horizontal, Length::points(3.0))
        .expect("set child horizontal margins");
    tree.set_relative_bottom_of(child, 10)
        .expect("set child bottom-of top anchor");
    tree.set_relative_top_of(child, 20)
        .expect("set child top-of bottom anchor");
    tree.set_relative_center(child, RelativeCenter::Both)
        .expect("set child center");
    tree.set_measure_func(child, Some(callback_measure))
        .expect("set child measure func");

    tree.append_child(root, child).expect("append child");
    tree.append_child(root, bottom_anchor)
        .expect("append bottom anchor");
    tree.append_child(root, top_anchor)
        .expect("append top anchor");

    run_standalone_head_to_head(tree, root, Constraints::definite(112.0, 202.0))
        .expect("relative center suppressed by sibling vertical edges with padding/border parity");
}

