#[test]
#[cfg(feature = "native-standalone")]
fn standalone_owned_tree_matches_cpp_for_relative_ordered_wrap_content_center_skips_display_none_extent_with_percent_margins(
) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_padding(root, StandaloneEdge::Left, Length::points(5.0))
        .expect("set root left padding");
    tree.set_padding(root, StandaloneEdge::Top, Length::points(4.0))
        .expect("set root top padding");
    tree.set_border(root, StandaloneEdge::Left, 1.0)
        .expect("set root left border");

    let hidden_extent = tree.create_default_node();
    tree.set_display(hidden_extent, Display::None)
        .expect("set hidden extent display");
    tree.set_width(hidden_extent, Length::points(320.0))
        .expect("set hidden extent width");
    tree.set_height(hidden_extent, Length::points(240.0))
        .expect("set hidden extent height");
    tree.set_relative_center(hidden_extent, RelativeCenter::Both)
        .expect("set hidden extent center");
    tree.set_order(hidden_extent, -8)
        .expect("set hidden extent order");

    let visible_extent = tree.create_default_measured_node(Size::new(132.0, 86.0));
    tree.set_margin(visible_extent, StandaloneEdge::Right, Length::points(7.0))
        .expect("set visible extent right margin");
    tree.set_margin(visible_extent, StandaloneEdge::Bottom, Length::points(5.0))
        .expect("set visible extent bottom margin");
    tree.set_order(visible_extent, -2)
        .expect("set visible extent order");

    let centered = tree.create_default_measured_node(Size::new(28.0, 16.0));
    tree.set_relative_center(centered, RelativeCenter::Both)
        .expect("set centered child");
    tree.set_margin(centered, StandaloneEdge::Left, Length::percent(4.0))
        .expect("set centered left margin");
    tree.set_margin(centered, StandaloneEdge::Right, Length::percent(6.0))
        .expect("set centered right margin");
    tree.set_margin(centered, StandaloneEdge::Top, Length::percent(5.0))
        .expect("set centered top margin");
    tree.set_margin(centered, StandaloneEdge::Bottom, Length::percent(3.0))
        .expect("set centered bottom margin");
    tree.set_order(centered, 3).expect("set centered order");

    tree.append_child(root, centered).expect("append centered");
    tree.append_child(root, hidden_extent)
        .expect("append hidden extent");
    tree.append_child(root, visible_extent)
        .expect("append visible extent");

    run_standalone_head_to_head(tree, root, Constraints::indefinite()).expect(
        "relative ordered wrap-content center skips display-none extent with percent margins parity",
    );
}

