#[cfg(feature = "native-standalone")]
fn flex_main_axis_auto_margin_direction_matrix_tree(
    flex_direction: FlexDirection,
    direction: Direction,
) -> (String, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    set_flex_content_box(&mut tree, root);
    tree.set_direction(root, direction)
        .expect("set root direction");
    tree.set_flex_direction(root, flex_direction)
        .expect("set root flex direction");
    tree.set_justify_content(root, JustifyContent::Center)
        .expect("set root justify content");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");
    tree.set_width(root, Length::points(100.0))
        .expect("set root width");
    tree.set_height(root, Length::points(100.0))
        .expect("set root height");

    let first = fixed_square_flex_node(&mut tree);
    let second = fixed_square_flex_node(&mut tree);
    tree.set_margin(
        second,
        main_start_standalone_edge(flex_direction, direction),
        Length::Auto,
    )
    .expect("set main-start auto margin");

    tree.append_child(root, first).expect("append first child");
    tree.append_child(root, second)
        .expect("append second child");

    (
        format!("flex {flex_direction:?} {direction:?} main-start auto-margin matrix"),
        tree,
        root,
        Constraints::definite(100.0, 100.0),
    )
}

#[cfg(feature = "native-standalone")]
fn main_start_standalone_edge(
    flex_direction: FlexDirection,
    direction: Direction,
) -> StandaloneEdge {
    match flex_direction {
        FlexDirection::Row => {
            if direction.is_rtl() {
                StandaloneEdge::Right
            } else {
                StandaloneEdge::Left
            }
        }
        FlexDirection::RowReverse => {
            if direction.is_rtl() {
                StandaloneEdge::Left
            } else {
                StandaloneEdge::Right
            }
        }
        FlexDirection::Column => StandaloneEdge::Top,
        FlexDirection::ColumnReverse => StandaloneEdge::Bottom,
    }
}

