#[cfg(feature = "native-standalone")]
fn flex_align_items_mapping_tree(
    flex_direction: FlexDirection,
    align_items: AlignItems,
) -> (String, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    set_flex_content_box(&mut tree, root);
    tree.set_flex_direction(root, flex_direction)
        .expect("set root flex direction");
    tree.set_justify_content(root, JustifyContent::FlexStart)
        .expect("set root justify content");
    tree.set_align_items(root, align_items)
        .expect("set root align items");
    tree.set_width(root, Length::points(120.0))
        .expect("set root width");
    tree.set_height(root, Length::points(80.0))
        .expect("set root height");

    let is_row = flex_direction.is_row();
    for (index, (main, cross)) in [(18.0, 8.0), (24.0, 12.0), (30.0, 16.0)]
        .into_iter()
        .enumerate()
    {
        let child = flex_align_items_child(&mut tree, is_row, main, cross, index == 1);
        tree.append_child(root, child)
            .unwrap_or_else(|_| panic!("append align-items child {index}"));
    }

    (
        format!("flex {flex_direction:?} align-items {align_items:?} mapping"),
        tree,
        root,
        Constraints::definite(120.0, 80.0),
    )
}

#[cfg(feature = "native-standalone")]
fn flex_align_items_child(
    tree: &mut StandaloneTree,
    is_row: bool,
    main: f32,
    cross: f32,
    auto_cross: bool,
) -> NodeId {
    let child = tree.create_default_node();
    set_flex_content_box(tree, child);
    tree.set_flex_basis(child, Length::points(main))
        .expect("set child flex basis");
    if is_row {
        tree.set_width(child, Length::points(main))
            .expect("set child width");
        tree.set_height(
            child,
            if auto_cross {
                Length::Auto
            } else {
                Length::points(cross)
            },
        )
        .expect("set child height");
    } else {
        tree.set_width(
            child,
            if auto_cross {
                Length::Auto
            } else {
                Length::points(cross)
            },
        )
        .expect("set child width");
        tree.set_height(child, Length::points(main))
            .expect("set child height");
    }
    child
}

#[cfg(feature = "native-standalone")]
fn flex_align_self_mapping_tree(
    flex_direction: FlexDirection,
    align_self: AlignItems,
) -> (String, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    set_flex_content_box(&mut tree, root);
    tree.set_flex_direction(root, flex_direction)
        .expect("set root flex direction");
    tree.set_justify_content(root, JustifyContent::FlexStart)
        .expect("set root justify content");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");
    tree.set_width(root, Length::points(120.0))
        .expect("set root width");
    tree.set_height(root, Length::points(80.0))
        .expect("set root height");

    let is_row = flex_direction.is_row();
    for (index, (main, cross)) in [(18.0, 8.0), (24.0, 12.0), (30.0, 16.0)]
        .into_iter()
        .enumerate()
    {
        let child = flex_align_items_child(&mut tree, is_row, main, cross, index == 1);
        if index == 1 {
            tree.set_align_self(child, Some(align_self))
                .expect("set child align self");
        }
        tree.append_child(root, child)
            .unwrap_or_else(|_| panic!("append align-self child {index}"));
    }

    (
        format!("flex {flex_direction:?} align-self {align_self:?} mapping"),
        tree,
        root,
        Constraints::definite(120.0, 80.0),
    )
}

#[cfg(feature = "native-standalone")]
fn flex_align_self_baseline_wrap_margins_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    set_flex_content_box(&mut tree, root);
    tree.set_flex_direction(root, FlexDirection::Row)
        .expect("set root flex direction");
    tree.set_flex_wrap(root, FlexWrap::Wrap)
        .expect("set root flex wrap");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");
    tree.set_align_content(root, AlignContent::FlexStart)
        .expect("set root align content");
    tree.set_justify_content(root, JustifyContent::FlexStart)
        .expect("set root justify content");
    tree.set_width(root, Length::points(54.0))
        .expect("set root width");
    tree.set_height(root, Length::points(72.0))
        .expect("set root height");
    tree.set_gap(root, StandaloneGap::Column, Length::points(2.0))
        .expect("set root column gap");
    tree.set_gap(root, StandaloneGap::Row, Length::points(3.0))
        .expect("set root row gap");

    let first_baseline = flex_measured_baseline_child(&mut tree, Size::new(18.0, 9.0), Some(4.0));
    tree.set_margin(first_baseline, StandaloneEdge::Top, Length::points(2.0))
        .expect("set first baseline top margin");
    tree.set_margin(first_baseline, StandaloneEdge::Bottom, Length::points(1.0))
        .expect("set first baseline bottom margin");

    let first_tall = flex_measured_baseline_child(&mut tree, Size::new(21.0, 18.0), None);
    tree.set_align_self(first_tall, Some(AlignItems::FlexStart))
        .expect("set first tall align self");
    tree.set_margin(first_tall, StandaloneEdge::Top, Length::points(1.0))
        .expect("set first tall top margin");
    tree.set_margin(first_tall, StandaloneEdge::Bottom, Length::points(2.0))
        .expect("set first tall bottom margin");

    let fallback_reference = flex_measured_baseline_child(&mut tree, Size::new(16.0, 13.0), None);
    tree.set_align_self(fallback_reference, Some(AlignItems::FlexStart))
        .expect("set fallback reference align self");
    tree.set_margin(fallback_reference, StandaloneEdge::Top, Length::points(1.0))
        .expect("set fallback reference top margin");

    let zero_baseline = flex_measured_baseline_child(&mut tree, Size::new(20.0, 0.0), Some(0.0));
    tree.set_margin(zero_baseline, StandaloneEdge::Bottom, Length::points(1.0))
        .expect("set zero baseline bottom margin");

    for (index, child) in [
        first_baseline,
        first_tall,
        fallback_reference,
        zero_baseline,
    ]
    .into_iter()
    .enumerate()
    {
        tree.append_child(root, child)
            .unwrap_or_else(|_| panic!("append baseline wrap child {index}"));
    }

    (tree, root, Constraints::definite(54.0, 72.0))
}

#[cfg(feature = "native-standalone")]
fn flex_measured_baseline_child(
    tree: &mut StandaloneTree,
    size: Size,
    baseline: Option<f32>,
) -> NodeId {
    let child = tree.create_default_measured_node(size);
    set_block_content_box(tree, child);
    tree.set_align_self(child, Some(AlignItems::Baseline))
        .expect("set child align self baseline");
    if let Some(baseline) = baseline {
        tree.set_baseline(child, Some(baseline))
            .expect("set child baseline");
    }
    child
}

