#[cfg(feature = "native-standalone")]
fn root_flex_fit_content_argument_tree(
    case_name: &'static str,
    flex_direction: FlexDirection,
    fit_content_size: Length,
    constraints: Constraints,
) -> (&'static str, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    set_flex_content_box(&mut tree, root);
    tree.set_flex_direction(root, flex_direction)
        .expect("set root flex direction");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");

    if flex_direction.is_row() {
        tree.set_width(root, fit_content_size)
            .expect("set root fit-content width");
        tree.set_height(root, Length::points(10.0))
            .expect("set root height");
    } else {
        tree.set_width(root, Length::points(10.0))
            .expect("set root width");
        tree.set_height(root, fit_content_size)
            .expect("set root fit-content height");
    }

    for index in 0..2 {
        let child = tree.create_default_node();
        set_flex_content_box(&mut tree, child);
        tree.set_flex_basis(child, Length::points(70.0))
            .expect("set child flex basis");
        tree.set_flex_shrink(child, 0.0)
            .expect("set child flex shrink");
        if flex_direction.is_row() {
            tree.set_height(child, Length::points(10.0))
                .expect("set child height");
        } else {
            tree.set_width(child, Length::points(10.0))
                .expect("set child width");
        }
        tree.append_child(root, child)
            .unwrap_or_else(|_| panic!("append fit-content root child {index}"));
    }

    (case_name, tree, root, constraints)
}

