#[cfg(feature = "native-standalone")]
fn fixed_main_axis_flex_node(
    tree: &mut StandaloneTree,
    flex_direction: FlexDirection,
    main_size: f32,
    cross_size: f32,
) -> NodeId {
    let node = tree.create_default_node();
    set_flex_content_box(tree, node);
    tree.set_flex_basis(node, Length::points(main_size))
        .expect("set fixed flex basis");
    tree.set_flex_shrink(node, 0.0)
        .expect("set fixed flex shrink");
    tree.set_width(
        node,
        Length::points(if flex_direction.is_row() {
            main_size
        } else {
            cross_size
        }),
    )
    .expect("set fixed flex width");
    tree.set_height(
        node,
        Length::points(if flex_direction.is_row() {
            cross_size
        } else {
            main_size
        }),
    )
    .expect("set fixed flex height");
    node
}

