#[cfg(feature = "native-standalone")]
fn owner_direction_inheritance_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_node(Style {
        display: Display::Flex,
        flex_direction: FlexDirection::Column,
        align_items: AlignItems::FlexStart,
        width: Length::points(30.0),
        height: Length::points(20.0),
        ..standalone_default_style()
    });

    let nested_style = Style {
        display: Display::Flex,
        flex_direction: FlexDirection::Row,
        align_items: AlignItems::FlexStart,
        width: Length::points(30.0),
        height: Length::points(10.0),
        ..standalone_default_style()
    };
    let leaf_style = Style {
        width: Length::points(10.0),
        height: Length::points(5.0),
        ..standalone_default_style()
    };

    let inherited_direction_container = tree.create_node(nested_style.clone());
    let inherited_direction_leaf = tree.create_node(leaf_style.clone());
    let explicit_ltr_container = tree.create_node(nested_style);
    let explicit_ltr_leaf = tree.create_node(leaf_style);

    tree.set_direction(explicit_ltr_container, Direction::Ltr)
        .expect("mark nested container direction explicit");

    tree.append_child(root, inherited_direction_container)
        .expect("append inherited-direction container");
    tree.append_child(inherited_direction_container, inherited_direction_leaf)
        .expect("append inherited-direction leaf");
    tree.append_child(root, explicit_ltr_container)
        .expect("append explicit-ltr container");
    tree.append_child(explicit_ltr_container, explicit_ltr_leaf)
        .expect("append explicit-ltr leaf");

    (
        tree,
        root,
        Constraints::new(SideConstraint::at_most(30.0), SideConstraint::at_most(20.0)),
    )
}

#[cfg(feature = "native-standalone")]
fn physical_pixel_rounding_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    set_flex_content_box(&mut tree, root);
    tree.set_flex_direction(root, FlexDirection::Row)
        .expect("set root flex direction");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");
    tree.set_width(root, Length::points(60.0))
        .expect("set root width");
    tree.set_height(root, Length::points(20.0))
        .expect("set root height");
    tree.set_gap(root, StandaloneGap::Column, Length::points(1.0))
        .expect("set root column gap");

    let default_rounding = tree.create_default_measured_node(Size::new(10.2, 4.2));
    let half_pixel_rounding = tree.create_default_node_with_config(
        StandaloneConfig::with_physical_pixels_per_layout_unit(2.0),
    );
    tree.set_measured_size(half_pixel_rounding, Some(Size::new(10.2, 4.2)))
        .expect("set configured measured size");

    tree.append_child(root, default_rounding)
        .expect("append default rounding child");
    tree.append_child(root, half_pixel_rounding)
        .expect("append half-pixel rounding child");

    (tree, root, Constraints::definite(60.0, 20.0))
}

#[cfg(feature = "native-standalone")]
fn tree_mutation_layout_order_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    set_flex_content_box(&mut tree, root);
    tree.set_flex_direction(root, FlexDirection::Row)
        .expect("set root flex direction");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");
    tree.set_width(root, Length::points(140.0))
        .expect("set root width");
    tree.set_height(root, Length::points(20.0))
        .expect("set root height");
    tree.set_gap(root, StandaloneGap::Column, Length::points(1.0))
        .expect("set root column gap");

    let staging_parent = tree.create_default_node();
    let first = fixed_flex_node(&mut tree, 10.0, 5.0);
    let second = fixed_flex_node(&mut tree, 11.0, 6.0);
    let inserted = fixed_flex_node(&mut tree, 12.0, 7.0);
    let clamped = fixed_flex_node(&mut tree, 13.0, 8.0);
    let negative = fixed_flex_node(&mut tree, 14.0, 9.0);
    let zero = fixed_flex_node(&mut tree, 15.0, 10.0);
    let moved = fixed_flex_node(&mut tree, 16.0, 11.0);

    tree.insert_child_or_append(root, first, None)
        .expect("none appends first child");
    tree.insert_child_or_append(root, second, None)
        .expect("none appends second child");
    tree.insert_child_or_append(root, inserted, Some(1))
        .expect("insert at middle index");
    tree.insert_child_or_append(root, clamped, Some(99))
        .expect("oversized index appends");
    tree.insert_child_at_standalone_index(root, negative, -2)
        .expect("negative index appends");
    tree.insert_child_at_standalone_index(root, zero, 0)
        .expect("zero index inserts before first child");

    tree.append_child(staging_parent, moved)
        .expect("append moved child to staging parent");
    tree.insert_child_before_or_append(root, moved, Some(second))
        .expect("reparent moved child before second");

    (tree, root, Constraints::definite(140.0, 20.0))
}

#[cfg(feature = "native-standalone")]
#[derive(Clone, Copy)]
struct MutationRelayoutIds {
    resized: NodeId,
    removed: NodeId,
    inserted: NodeId,
    trailing: NodeId,
}

#[cfg(feature = "native-standalone")]
fn mutation_relayout_after_clean_layout_tree(
) -> (StandaloneTree, NodeId, Constraints, MutationRelayoutIds) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    set_flex_content_box(&mut tree, root);
    tree.set_flex_direction(root, FlexDirection::Row)
        .expect("set root flex direction");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");
    tree.set_width(root, Length::points(120.0))
        .expect("set root width");
    tree.set_height(root, Length::points(30.0))
        .expect("set root height");
    tree.set_gap(root, StandaloneGap::Column, Length::points(1.0))
        .expect("set root column gap");

    let leading = fixed_flex_node(&mut tree, 12.0, 8.0);
    let resized = tree.create_default_measured_node(Size::new(9.0, 6.0));
    let removed = fixed_flex_node(&mut tree, 7.0, 5.0);
    let trailing = fixed_flex_node(&mut tree, 10.0, 10.0);
    let inserted = fixed_flex_node(&mut tree, 18.0, 12.0);

    tree.append_child(root, leading)
        .expect("append leading child");
    tree.append_child(root, resized)
        .expect("append measured child");
    tree.append_child(root, removed)
        .expect("append child removed before relayout");
    tree.append_child(root, trailing)
        .expect("append trailing child");

    (
        tree,
        root,
        Constraints::definite(120.0, 30.0),
        MutationRelayoutIds {
            resized,
            removed,
            inserted,
            trailing,
        },
    )
}

#[cfg(feature = "native-standalone")]
fn public_size_setter_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Flex)
        .expect("set root display");
    tree.set_flex_direction(root, FlexDirection::Row)
        .expect("set root flex direction");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");
    tree.set_justify_content(root, JustifyContent::FlexStart)
        .expect("set root justify content");
    tree.set_width(root, Length::points(70.0))
        .expect("set root width");
    tree.set_height(root, Length::points(32.0))
        .expect("set root height");
    tree.set_min_width(root, Length::points(40.0))
        .expect("set root min width");
    tree.set_max_width(root, Length::points(90.0))
        .expect("set root max width");
    tree.set_gap(root, StandaloneGap::Column, Length::points(3.0))
        .expect("set root column gap");

    let child = tree.create_default_measured_node(Size::new(12.0, 8.0));
    tree.set_flex(child, 1.0).expect("set child flex shorthand");
    tree.set_min_height(child, Length::points(6.0))
        .expect("set child min height");
    tree.set_max_height(child, Length::points(20.0))
        .expect("set child max height");
    tree.append_child(root, child).expect("append child");
    let second_child = tree.create_default_measured_node(Size::new(9.0, 7.0));
    tree.set_order(second_child, -1)
        .expect("set second child order");
    tree.append_child(root, second_child)
        .expect("append second child");

    (tree, root, Constraints::definite(100.0, 60.0))
}

#[cfg(feature = "native-standalone")]
fn callback_measure(constraints: Constraints) -> Size {
    let width = constraints.width.bounded_size().unwrap_or(20.0) - 3.0;
    let height = constraints.height.bounded_size().unwrap_or(12.0) - 1.0;
    Size::new(width, height)
}

#[cfg(feature = "native-standalone")]
fn callback_baseline(content_size: Size) -> f32 {
    content_size.height - 2.0
}

#[cfg(feature = "native-standalone")]
fn cross_axis_bounded_measure(constraints: Constraints) -> Size {
    Size::new(constraints.width.bounded_size().unwrap_or(150.0), 10.0)
}

#[cfg(feature = "native-standalone")]
fn simple_tree_callback_measure(constraints: Constraints) -> Size {
    let width = constraints
        .width
        .bounded_size()
        .map_or(17.0, |size| (size - 3.0).max(1.0));
    let height = constraints
        .height
        .bounded_size()
        .map_or(11.0, |size| (size - 2.0).max(1.0));
    Size::new(width, height)
}

#[cfg(feature = "native-standalone")]
fn simple_tree_callback_baseline(content_size: Size) -> f32 {
    (content_size.height - 2.0).max(0.0)
}

#[cfg(feature = "native-standalone")]
fn measured_baseline_callback_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_node(Style {
        display: Display::Flex,
        flex_direction: FlexDirection::Row,
        align_items: AlignItems::Baseline,
        padding: Rect::all(Length::points(1.0)),
        ..standalone_default_style()
    });

    let callback_child = tree.create_default_node();
    tree.set_measure_func(callback_child, Some(callback_measure))
        .expect("set callback measure");
    tree.set_baseline_func(callback_child, Some(callback_baseline))
        .expect("set callback baseline");

    let static_child = tree.create_measured_node_with_baseline(
        standalone_default_style(),
        Size::new(10.0, 7.0),
        3.0,
    );
    tree.append_child(root, callback_child)
        .expect("append callback child");
    tree.append_child(root, static_child)
        .expect("append static child");

    (
        tree,
        root,
        Constraints::new(SideConstraint::at_most(80.0), SideConstraint::indefinite()),
    )
}

#[cfg(feature = "native-standalone")]
fn wrapped_flex_measured_callback_baseline_tree(
) -> (&'static str, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    set_flex_content_box(&mut tree, root);
    tree.set_width(root, Length::points(136.0))
        .expect("set root width");
    tree.set_height(root, Length::points(58.0))
        .expect("set root height");
    tree.set_min_width(root, Length::points(72.0))
        .expect("set root min width");
    tree.set_max_width(root, Length::points(180.0))
        .expect("set root max width");
    tree.set_min_height(root, Length::points(28.0))
        .expect("set root min height");
    tree.set_max_height(root, Length::points(92.0))
        .expect("set root max height");
    tree.set_padding(root, StandaloneEdge::All, Length::points(1.0))
        .expect("set root padding");
    tree.set_border(root, StandaloneEdge::All, 0.5)
        .expect("set root border");
    tree.set_flex_wrap(root, FlexWrap::Wrap)
        .expect("set root wrap");
    tree.set_align_items(root, AlignItems::Baseline)
        .expect("set root align items");
    tree.set_justify_content(root, JustifyContent::FlexStart)
        .expect("set root justify content");
    tree.set_align_content(root, AlignContent::FlexStart)
        .expect("set root align content");
    tree.set_gap(root, StandaloneGap::Column, Length::points(1.0))
        .expect("set root column gap");
    tree.set_gap(root, StandaloneGap::Row, Length::points(1.0))
        .expect("set root row gap");

    let measured_with_baseline = tree.create_default_node();
    set_block_content_box(&mut tree, measured_with_baseline);
    tree.set_width(
        measured_with_baseline,
        Length::fit_content(Some(BaseLength::fixed(36.0))),
    )
    .expect("set measured baseline width");
    tree.set_align_self(measured_with_baseline, Some(AlignItems::Baseline))
        .expect("set measured baseline align self");
    tree.set_margin(
        measured_with_baseline,
        StandaloneEdge::Top,
        Length::points(0.5),
    )
    .expect("set measured baseline top margin");
    tree.set_measure_func(measured_with_baseline, Some(simple_tree_callback_measure))
        .expect("set measured baseline measure func");
    tree.set_baseline_func(measured_with_baseline, Some(simple_tree_callback_baseline))
        .expect("set measured baseline func");

    let measured = tree.create_default_node();
    set_block_content_box(&mut tree, measured);
    tree.set_height(measured, Length::fit_content(Some(BaseLength::fixed(18.0))))
        .expect("set measured height");
    tree.set_min_height(measured, Length::points(10.0))
        .expect("set measured min height");
    tree.set_margin(measured, StandaloneEdge::Left, Length::points(1.0))
        .expect("set measured left margin");
    tree.set_margin(measured, StandaloneEdge::Right, Length::points(0.5))
        .expect("set measured right margin");
    tree.set_margin(measured, StandaloneEdge::Top, Length::points(0.5))
        .expect("set measured top margin");
    tree.set_measure_func(measured, Some(simple_tree_callback_measure))
        .expect("set measured measure func");

    let static_measured_with_baseline = tree.create_default_measured_node(Size::new(25.0, 14.0));
    set_block_content_box(&mut tree, static_measured_with_baseline);
    tree.set_min_width(static_measured_with_baseline, Length::points(20.0))
        .expect("set static baseline min width");
    tree.set_max_height(static_measured_with_baseline, Length::points(32.0))
        .expect("set static baseline max height");
    tree.set_align_self(static_measured_with_baseline, Some(AlignItems::Baseline))
        .expect("set static baseline align self");
    tree.set_margin(
        static_measured_with_baseline,
        StandaloneEdge::Right,
        Length::points(1.0),
    )
    .expect("set static baseline right margin");
    tree.set_margin(
        static_measured_with_baseline,
        StandaloneEdge::Top,
        Length::points(0.5),
    )
    .expect("set static baseline top margin");
    tree.set_baseline(static_measured_with_baseline, Some(8.0))
        .expect("set static baseline");

    let static_measured = tree.create_default_measured_node(Size::new(28.0, 16.0));
    set_block_content_box(&mut tree, static_measured);
    tree.set_max_width(static_measured, Length::points(54.0))
        .expect("set static measured max width");
    tree.set_margin(static_measured, StandaloneEdge::Left, Length::points(1.0))
        .expect("set static measured left margin");
    tree.set_margin(static_measured, StandaloneEdge::Top, Length::points(0.5))
        .expect("set static measured top margin");

    tree.append_child(root, measured_with_baseline)
        .expect("append measured baseline child");
    tree.append_child(root, measured)
        .expect("append measured child");
    tree.append_child(root, static_measured_with_baseline)
        .expect("append static measured baseline child");
    tree.append_child(root, static_measured)
        .expect("append static measured child");

    (
        "wrapped flex measured callback exports C++ first-line baseline",
        tree,
        root,
        Constraints::definite(320.0, 80.0),
    )
}

