#[cfg(feature = "native-standalone")]
fn grid_positioning_and_fixed_descendant_tree_for_direction(
    direction: Direction,
) -> (String, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Block)
        .expect("set root display");
    tree.set_direction(root, direction)
        .expect("set root direction");
    tree.set_width(root, Length::points(340.0))
        .expect("set root width");
    tree.set_height(root, Length::points(568.0))
        .expect("set root height");

    let grid = tree.create_default_node();
    tree.set_display(grid, Display::Grid)
        .expect("set grid display");
    tree.set_direction(grid, direction)
        .expect("set grid direction");
    tree.set_width(grid, Length::points(320.0))
        .expect("set grid width");
    tree.set_height(grid, Length::points(64.0))
        .expect("set grid height");
    tree.set_padding(grid, StandaloneEdge::Left, Length::points(4.0))
        .expect("set grid left padding");
    tree.set_padding(grid, StandaloneEdge::Right, Length::points(5.0))
        .expect("set grid right padding");
    tree.set_padding(grid, StandaloneEdge::Top, Length::points(6.0))
        .expect("set grid top padding");
    tree.set_padding(grid, StandaloneEdge::Bottom, Length::points(7.0))
        .expect("set grid bottom padding");
    tree.set_border(grid, StandaloneEdge::Left, 1.0)
        .expect("set grid left border");
    tree.set_border(grid, StandaloneEdge::Right, 2.0)
        .expect("set grid right border");
    tree.set_border(grid, StandaloneEdge::Top, 3.0)
        .expect("set grid top border");
    tree.set_border(grid, StandaloneEdge::Bottom, 4.0)
        .expect("set grid bottom border");
    tree.set_grid_template_columns(grid, [Length::points(24.0), Length::points(30.0)])
        .expect("set grid columns");
    tree.set_grid_template_rows(grid, [Length::points(18.0), Length::points(20.0)])
        .expect("set grid rows");
    tree.set_grid_auto_columns(grid, [Length::points(11.0)])
        .expect("set grid auto columns");
    tree.set_grid_auto_rows(grid, [Length::points(13.0)])
        .expect("set grid auto rows");
    tree.set_grid_auto_flow(grid, GridAutoFlow::RowDense)
        .expect("set grid auto flow");
    tree.set_gap(grid, StandaloneGap::Column, Length::points(5.0))
        .expect("set grid column gap");
    tree.set_gap(grid, StandaloneGap::Row, Length::points(3.0))
        .expect("set grid row gap");
    tree.set_justify_content(grid, JustifyContent::Center)
        .expect("set grid justify content");
    tree.set_align_content(grid, AlignContent::Center)
        .expect("set grid align content");
    tree.set_justify_items(grid, JustifyItems::Center)
        .expect("set grid justify items");
    tree.set_align_items(grid, AlignItems::Center)
        .expect("set grid align items");

    let in_flow = tree.create_default_node();
    tree.set_display(in_flow, Display::Block)
        .expect("set in-flow display");
    tree.set_width(in_flow, Length::points(10.0))
        .expect("set in-flow width");
    tree.set_height(in_flow, Length::points(6.0))
        .expect("set in-flow height");
    tree.set_grid_column_start(in_flow, Some(2))
        .expect("set in-flow grid column start");
    tree.set_grid_column_end(in_flow, Some(3))
        .expect("set in-flow grid column end");
    tree.set_grid_row_start(in_flow, Some(2))
        .expect("set in-flow grid row start");
    tree.set_grid_row_end(in_flow, Some(3))
        .expect("set in-flow grid row end");
    tree.set_justify_self(in_flow, JustifyItems::Start)
        .expect("set in-flow justify self");
    tree.set_align_self(in_flow, Some(AlignItems::FlexEnd))
        .expect("set in-flow align self");

    let absolute = tree.create_default_node();
    tree.set_display(absolute, Display::Block)
        .expect("set absolute display");
    tree.set_position_type(absolute, PositionType::Absolute)
        .expect("set absolute position");
    tree.set_width(absolute, Length::points(12.0))
        .expect("set absolute width");
    tree.set_height(absolute, Length::points(8.0))
        .expect("set absolute height");
    tree.set_grid_column_start(absolute, Some(1))
        .expect("set absolute grid column start");
    tree.set_grid_column_end(absolute, Some(2))
        .expect("set absolute grid column end");
    tree.set_grid_row_start(absolute, Some(1))
        .expect("set absolute grid row start");
    tree.set_grid_row_end(absolute, Some(2))
        .expect("set absolute grid row end");
    tree.set_position(absolute, StandaloneEdge::Right, Length::points(2.0))
        .expect("set absolute right");
    tree.set_position(absolute, StandaloneEdge::Top, Length::points(3.0))
        .expect("set absolute top");
    tree.set_margin(absolute, StandaloneEdge::Horizontal, Length::points(1.0))
        .expect("set absolute horizontal margin");
    tree.set_justify_self(absolute, JustifyItems::End)
        .expect("set absolute justify self");
    tree.set_align_self(absolute, Some(AlignItems::Start))
        .expect("set absolute align self");

    let fixed = tree.create_default_node();
    tree.set_display(fixed, Display::Block)
        .expect("set fixed display");
    tree.set_position_type(fixed, PositionType::Fixed)
        .expect("set fixed position");
    tree.set_grid_column_start(fixed, Some(1))
        .expect("set fixed grid column start");
    tree.set_grid_column_end(fixed, Some(2))
        .expect("set fixed grid column end");
    tree.set_grid_row_start(fixed, Some(1))
        .expect("set fixed grid row start");
    tree.set_grid_row_end(fixed, Some(2))
        .expect("set fixed grid row end");
    tree.set_position(fixed, StandaloneEdge::Left, Length::percent(10.0))
        .expect("set fixed left");
    tree.set_position(fixed, StandaloneEdge::Right, Length::calc(2.0, 15.0))
        .expect("set fixed right");
    tree.set_position(fixed, StandaloneEdge::Top, Length::calc(1.0, 20.0))
        .expect("set fixed top");
    tree.set_position(fixed, StandaloneEdge::Bottom, Length::percent(12.0))
        .expect("set fixed bottom");
    tree.set_margin(fixed, StandaloneEdge::Left, Length::points(1.0))
        .expect("set fixed left margin");
    tree.set_margin(fixed, StandaloneEdge::Bottom, Length::points(1.0))
        .expect("set fixed bottom margin");
    tree.set_padding(fixed, StandaloneEdge::All, Length::points(1.0))
        .expect("set fixed padding");
    tree.set_border(fixed, StandaloneEdge::All, 1.0)
        .expect("set fixed border");

    tree.append_child(root, grid).expect("append grid");
    tree.append_child(grid, in_flow)
        .expect("append in-flow grid child");
    tree.append_child(grid, absolute)
        .expect("append absolute grid child");
    tree.append_child(grid, fixed).expect("append fixed child");

    (
        format!("grid {direction:?} positioning and fixed descendant"),
        tree,
        root,
        Constraints::new(
            SideConstraint::definite(340.0),
            SideConstraint::indefinite(),
        ),
    )
}

