#[cfg(feature = "native-standalone")]
fn grid_content_alignment_mapping_tree_for_direction(
    direction: Direction,
    justify_content: JustifyContent,
    align_content: AlignContent,
) -> (String, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Grid)
        .expect("set root display");
    tree.set_direction(root, direction)
        .expect("set root direction");
    tree.set_width(root, Length::points(80.0))
        .expect("set root width");
    tree.set_height(root, Length::points(70.0))
        .expect("set root height");
    tree.set_grid_template_columns(root, [Length::points(10.0), Length::points(20.0)])
        .expect("set root grid columns");
    tree.set_grid_template_rows(root, [Length::points(8.0), Length::points(12.0)])
        .expect("set root grid rows");
    tree.set_gap(root, StandaloneGap::Column, Length::points(3.0))
        .expect("set root column gap");
    tree.set_gap(root, StandaloneGap::Row, Length::points(4.0))
        .expect("set root row gap");
    tree.set_justify_content(root, justify_content)
        .expect("set root justify content");
    tree.set_align_content(root, align_content)
        .expect("set root align content");
    tree.set_justify_items(root, JustifyItems::Start)
        .expect("set root justify items");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");

    let first = grid_alignment_marker(&mut tree, 5.0, 4.0, 1, 1);
    let second = grid_alignment_marker(&mut tree, 7.0, 6.0, 2, 2);
    tree.append_child(root, first)
        .expect("append first grid alignment marker");
    tree.append_child(root, second)
        .expect("append second grid alignment marker");

    (
        format!(
            "grid {direction:?} justify-content {justify_content:?} align-content {align_content:?} mapping"
        ),
        tree,
        root,
        Constraints::definite(80.0, 70.0),
    )
}

#[cfg(feature = "native-standalone")]
fn grid_alignment_marker(
    tree: &mut StandaloneTree,
    width: f32,
    height: f32,
    column: i32,
    row: i32,
) -> NodeId {
    let child = tree.create_default_node();
    set_block_content_box(tree, child);
    tree.set_width(child, Length::points(width))
        .expect("set marker width");
    tree.set_height(child, Length::points(height))
        .expect("set marker height");
    tree.set_grid_column_start(child, Some(column))
        .expect("set marker grid column start");
    tree.set_grid_row_start(child, Some(row))
        .expect("set marker grid row start");
    child
}

