#[cfg(feature = "native-standalone")]
fn block_fit_content_measured_callback_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Block)
        .expect("set root display");
    tree.set_box_sizing(root, BoxSizing::ContentBox)
        .expect("set root box sizing");
    tree.set_width(root, Length::points(320.0))
        .expect("set root width");
    tree.set_height(root, Length::points(80.0))
        .expect("set root height");

    let container = tree.create_default_node();
    tree.set_display(container, Display::Block)
        .expect("set container display");
    tree.set_box_sizing(container, BoxSizing::ContentBox)
        .expect("set container box sizing");
    tree.set_width(
        container,
        Length::fit_content(Some(BaseLength::fixed(126.0))),
    )
    .expect("set container width");
    tree.set_height(
        container,
        Length::fit_content(Some(BaseLength::fixed(44.0))),
    )
    .expect("set container height");
    tree.set_min_width(container, Length::points(72.0))
        .expect("set container min width");
    tree.set_max_width(container, Length::points(180.0))
        .expect("set container max width");
    tree.set_min_height(container, Length::points(28.0))
        .expect("set container min height");
    tree.set_max_height(container, Length::points(92.0))
        .expect("set container max height");
    tree.set_padding(container, StandaloneEdge::All, Length::points(1.0))
        .expect("set container padding");
    tree.set_margin(container, StandaloneEdge::Left, Length::points(1.0))
        .expect("set container left margin");
    tree.set_margin(container, StandaloneEdge::Top, Length::points(1.0))
        .expect("set container top margin");

    let measured_with_baseline = tree.create_default_node();
    tree.set_display(measured_with_baseline, Display::Block)
        .expect("set measured baseline display");
    tree.set_box_sizing(measured_with_baseline, BoxSizing::ContentBox)
        .expect("set measured baseline box sizing");
    tree.set_width(
        measured_with_baseline,
        Length::fit_content(Some(BaseLength::fixed(36.0))),
    )
    .expect("set measured baseline width");
    tree.set_align_self(measured_with_baseline, Some(AlignItems::Baseline))
        .expect("set measured baseline align self");
    tree.set_measure_func(measured_with_baseline, Some(callback_measure))
        .expect("set measured baseline measure func");
    tree.set_baseline_func(measured_with_baseline, Some(callback_baseline))
        .expect("set measured baseline func");

    let measured = tree.create_default_node();
    tree.set_display(measured, Display::Block)
        .expect("set measured display");
    tree.set_box_sizing(measured, BoxSizing::ContentBox)
        .expect("set measured box sizing");
    tree.set_height(measured, Length::fit_content(Some(BaseLength::fixed(18.0))))
        .expect("set measured height");
    tree.set_min_height(measured, Length::points(10.0))
        .expect("set measured min height");
    tree.set_margin(measured, StandaloneEdge::Left, Length::points(1.0))
        .expect("set measured left margin");
    tree.set_margin(measured, StandaloneEdge::Right, Length::points(0.5))
        .expect("set measured right margin");
    tree.set_measure_func(measured, Some(callback_measure))
        .expect("set measured measure func");

    let static_measured_with_baseline = tree.create_default_measured_node(Size::new(24.0, 13.0));
    tree.set_display(static_measured_with_baseline, Display::Block)
        .expect("set static baseline display");
    tree.set_box_sizing(static_measured_with_baseline, BoxSizing::ContentBox)
        .expect("set static baseline box sizing");
    tree.set_min_width(static_measured_with_baseline, Length::points(20.0))
        .expect("set static baseline min width");
    tree.set_max_height(static_measured_with_baseline, Length::points(32.0))
        .expect("set static baseline max height");
    tree.set_align_self(static_measured_with_baseline, Some(AlignItems::Baseline))
        .expect("set static baseline align self");
    tree.set_baseline(static_measured_with_baseline, Some(8.0))
        .expect("set static baseline");

    let static_measured = tree.create_default_measured_node(Size::new(27.0, 15.0));
    tree.set_display(static_measured, Display::Block)
        .expect("set static measured display");
    tree.set_box_sizing(static_measured, BoxSizing::ContentBox)
        .expect("set static measured box sizing");
    tree.set_max_width(static_measured, Length::points(54.0))
        .expect("set static measured max width");
    tree.set_margin(static_measured, StandaloneEdge::Left, Length::points(1.0))
        .expect("set static measured left margin");

    tree.append_child(root, container)
        .expect("append container");
    tree.append_child(container, measured_with_baseline)
        .expect("append measured baseline child");
    tree.append_child(container, measured)
        .expect("append measured child");
    tree.append_child(container, static_measured_with_baseline)
        .expect("append static measured baseline child");
    tree.append_child(container, static_measured)
        .expect("append static measured child");

    (tree, root, Constraints::definite(320.0, 80.0))
}

