#[cfg(feature = "native-standalone")]
fn append_default_grid_children(
    tree: &mut StandaloneTree,
    root: NodeId,
    count: usize,
    case_name: &str,
) {
    for index in 0..count {
        let child = tree.create_default_node();
        tree.append_child(root, child)
            .unwrap_or_else(|_| panic!("append {case_name} child {index}"));
    }
}

#[cfg(feature = "native-standalone")]
fn append_positioned_grid_child(
    tree: &mut StandaloneTree,
    root: NodeId,
    column: i32,
    row: i32,
    case_name: &str,
) -> NodeId {
    let child = tree.create_default_node();
    tree.set_grid_column_start(child, Some(column))
        .unwrap_or_else(|_| panic!("set {case_name} child column"));
    tree.set_grid_row_start(child, Some(row))
        .unwrap_or_else(|_| panic!("set {case_name} child row"));
    tree.append_child(root, child)
        .unwrap_or_else(|_| panic!("append {case_name} child"));
    child
}

#[cfg(feature = "native-standalone")]
fn append_measured_grid_child(
    tree: &mut StandaloneTree,
    root: NodeId,
    size: Size,
    column: i32,
    row: i32,
    case_name: &str,
) -> NodeId {
    let child = tree.create_default_measured_node(size);
    tree.set_display(child, Display::Block)
        .unwrap_or_else(|_| panic!("set {case_name} child display"));
    tree.set_grid_column_start(child, Some(column))
        .unwrap_or_else(|_| panic!("set {case_name} child column"));
    tree.set_grid_row_start(child, Some(row))
        .unwrap_or_else(|_| panic!("set {case_name} child row"));
    tree.set_justify_self(child, JustifyItems::Start)
        .unwrap_or_else(|_| panic!("set {case_name} child justify-self"));
    tree.set_align_self(child, Some(AlignItems::FlexStart))
        .unwrap_or_else(|_| panic!("set {case_name} child align-self"));
    tree.append_child(root, child)
        .unwrap_or_else(|_| panic!("append {case_name} child"));
    child
}

