#[cfg(feature = "native-standalone")]
fn grid_align_content_track_group_tree(
    case_name: &'static str,
    align_content: AlignContent,
    height: f32,
    row_gap: Option<f32>,
) -> (&'static str, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Grid)
        .expect("set root display");
    tree.set_align_content(root, align_content)
        .expect("set root align content");
    tree.set_width(root, Length::points(20.0))
        .expect("set root width");
    tree.set_height(root, Length::points(height))
        .expect("set root height");
    tree.set_grid_template_columns(root, [Length::points(20.0)])
        .expect("set grid columns");
    tree.set_grid_template_rows(root, [Length::points(20.0), Length::points(20.0)])
        .expect("set grid rows");
    if let Some(row_gap) = row_gap {
        tree.set_gap(root, StandaloneGap::Row, Length::points(row_gap))
            .expect("set grid row gap");
    }
    append_default_grid_children(&mut tree, root, 2, case_name);

    (case_name, tree, root, Constraints::definite(20.0, height))
}

