#[cfg(feature = "native-standalone")]
fn rtl_grid_justify_content_track_group_tree(
    case_name: &'static str,
    justify_content: JustifyContent,
    width: f32,
    columns: [Length; 2],
) -> (&'static str, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Grid)
        .expect("set root display");
    tree.set_direction(root, Direction::Rtl)
        .expect("set root direction");
    tree.set_justify_content(root, justify_content)
        .expect("set root justify content");
    tree.set_width(root, Length::points(width))
        .expect("set root width");
    tree.set_height(root, Length::points(10.0))
        .expect("set root height");
    tree.set_grid_template_columns(root, columns)
        .expect("set grid columns");
    tree.set_grid_template_rows(root, [Length::points(10.0)])
        .expect("set grid rows");
    tree.set_gap(root, StandaloneGap::Column, Length::points(10.0))
        .expect("set grid column gap");
    tree.set_justify_items(root, JustifyItems::Start)
        .expect("set root justify items");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set root align items");

    append_rtl_grid_measured_child(&mut tree, root, 1, Size::new(5.0, 10.0), case_name);
    append_rtl_grid_measured_child(&mut tree, root, 2, Size::new(7.0, 10.0), case_name);

    (case_name, tree, root, Constraints::definite(width, 10.0))
}

#[cfg(feature = "native-standalone")]
fn append_rtl_grid_measured_child(
    tree: &mut StandaloneTree,
    root: NodeId,
    column: i32,
    size: Size,
    case_name: &str,
) -> NodeId {
    let child = tree.create_default_measured_node(size);
    tree.set_display(child, Display::Block)
        .unwrap_or_else(|_| panic!("set {case_name} child display"));
    tree.set_grid_column_start(child, Some(column))
        .unwrap_or_else(|_| panic!("set {case_name} child column"));
    tree.set_grid_row_start(child, Some(1))
        .unwrap_or_else(|_| panic!("set {case_name} child row"));
    tree.append_child(root, child)
        .unwrap_or_else(|_| panic!("append {case_name} child"));
    child
}

