#[cfg(feature = "native-standalone")]
fn grid_intrinsic_growth_planned_increases_source_order_tree(
    first_then_second: bool,
) -> (&'static str, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Grid)
        .expect("set root display");
    tree.set_grid_template_columns(root, [Length::Auto, Length::Auto, Length::Auto])
        .expect("set grid columns");
    tree.set_grid_template_rows(root, [Length::points(10.0)])
        .expect("set grid rows");

    let first_span = tree.create_default_measured_node(Size::new(80.0, 10.0));
    tree.set_grid_column_start(first_span, Some(1))
        .expect("set first child column");
    tree.set_grid_column_span(first_span, 2)
        .expect("set first child column span");
    tree.set_grid_row_start(first_span, Some(1))
        .expect("set first child row");
    tree.set_justify_self(first_span, JustifyItems::Start)
        .expect("set first child justify self");
    tree.set_align_self(first_span, Some(AlignItems::FlexStart))
        .expect("set first child align self");

    let second_span = tree.create_default_measured_node(Size::new(100.0, 10.0));
    tree.set_grid_column_start(second_span, Some(2))
        .expect("set second child column");
    tree.set_grid_column_span(second_span, 2)
        .expect("set second child column span");
    tree.set_grid_row_start(second_span, Some(1))
        .expect("set second child row");
    tree.set_justify_self(second_span, JustifyItems::Start)
        .expect("set second child justify self");
    tree.set_align_self(second_span, Some(AlignItems::FlexStart))
        .expect("set second child align self");

    if first_then_second {
        tree.append_child(root, first_span)
            .expect("append first intrinsic span");
        tree.append_child(root, second_span)
            .expect("append second intrinsic span");
    } else {
        tree.append_child(root, second_span)
            .expect("append second intrinsic span");
        tree.append_child(root, first_span)
            .expect("append first intrinsic span");
    }

    (
        if first_then_second {
            "grid intrinsic growth planned increases first then second"
        } else {
            "grid intrinsic growth planned increases second then first"
        },
        tree,
        root,
        Constraints::indefinite(),
    )
}

