#[cfg(feature = "native-standalone")]
#[derive(Clone, Copy)]
struct GridAutoPlacementMatrixCase {
    name: &'static str,
    flow: GridAutoFlow,
    kind: GridAutoPlacementMatrixKind,
}

#[cfg(feature = "native-standalone")]
#[derive(Clone, Copy)]
enum GridAutoPlacementMatrixKind {
    FullyAuto,
    LockedAxis,
    LeadingImplicit,
}

#[cfg(feature = "native-standalone")]
fn grid_auto_placement_matrix_tree(
    case: GridAutoPlacementMatrixCase,
) -> (StandaloneTree, NodeId, Constraints) {
    match case.kind {
        GridAutoPlacementMatrixKind::FullyAuto => grid_fully_auto_placement_matrix_tree(case.flow),
        GridAutoPlacementMatrixKind::LockedAxis => {
            grid_locked_axis_auto_placement_matrix_tree(case.flow)
        }
        GridAutoPlacementMatrixKind::LeadingImplicit => {
            grid_leading_implicit_auto_placement_matrix_tree(case.flow)
        }
    }
}

#[cfg(feature = "native-standalone")]
fn grid_fully_auto_placement_matrix_tree(
    flow: GridAutoFlow,
) -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = grid_auto_placement_matrix_root(&mut tree, flow);
    let is_column_flow = matches!(flow, GridAutoFlow::Column | GridAutoFlow::ColumnDense);

    for (index, span) in [2, 2, 1].into_iter().enumerate() {
        let child = tree.create_default_measured_node(Size::new(6.0 + index as f32, 5.0));
        tree.set_display(child, Display::Block)
            .expect("set fully-auto grid child display");
        if is_column_flow {
            tree.set_grid_row_span(child, span)
                .expect("set fully-auto grid child row span");
        } else {
            tree.set_grid_column_span(child, span)
                .expect("set fully-auto grid child column span");
        }
        tree.append_child(root, child)
            .unwrap_or_else(|_| panic!("append fully-auto grid child {index}"));
    }

    (tree, root, Constraints::definite(60.0, 60.0))
}

#[cfg(feature = "native-standalone")]
fn grid_locked_axis_auto_placement_matrix_tree(
    flow: GridAutoFlow,
) -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = grid_auto_placement_matrix_root(&mut tree, flow);
    let is_column_flow = matches!(flow, GridAutoFlow::Column | GridAutoFlow::ColumnDense);

    let blocker = tree.create_default_measured_node(Size::new(6.0, 6.0));
    tree.set_display(blocker, Display::Block)
        .expect("set locked-axis blocker display");
    let spanning = tree.create_default_measured_node(Size::new(8.0, 6.0));
    tree.set_display(spanning, Display::Block)
        .expect("set locked-axis spanning display");
    let backfill_candidate = tree.create_default_measured_node(Size::new(5.0, 5.0));
    tree.set_display(backfill_candidate, Display::Block)
        .expect("set locked-axis candidate display");

    if is_column_flow {
        tree.set_grid_column_start(blocker, Some(1))
            .expect("set blocker column start");
        tree.set_grid_row_start(blocker, Some(2))
            .expect("set blocker row start");
        tree.set_grid_column_start(spanning, Some(1))
            .expect("set spanning column start");
        tree.set_grid_row_span(spanning, 2)
            .expect("set spanning row span");
        tree.set_grid_column_start(backfill_candidate, Some(1))
            .expect("set candidate column start");
    } else {
        tree.set_grid_column_start(blocker, Some(2))
            .expect("set blocker column start");
        tree.set_grid_row_start(blocker, Some(1))
            .expect("set blocker row start");
        tree.set_grid_row_start(spanning, Some(1))
            .expect("set spanning row start");
        tree.set_grid_column_span(spanning, 2)
            .expect("set spanning column span");
        tree.set_grid_row_start(backfill_candidate, Some(1))
            .expect("set candidate row start");
    }

    tree.append_child(root, blocker)
        .expect("append locked-axis blocker");
    tree.append_child(root, spanning)
        .expect("append locked-axis spanning child");
    tree.append_child(root, backfill_candidate)
        .expect("append locked-axis backfill candidate");

    (tree, root, Constraints::definite(60.0, 60.0))
}

#[cfg(feature = "native-standalone")]
fn grid_leading_implicit_auto_placement_matrix_tree(
    flow: GridAutoFlow,
) -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = grid_auto_placement_matrix_root(&mut tree, flow);
    let is_column_flow = matches!(flow, GridAutoFlow::Column | GridAutoFlow::ColumnDense);

    let blocker = tree.create_default_measured_node(Size::new(6.0, 6.0));
    tree.set_display(blocker, Display::Block)
        .expect("set leading implicit blocker display");
    if is_column_flow {
        tree.set_grid_column_start(blocker, Some(1))
            .expect("set blocker column start");
        tree.set_grid_row_start(blocker, Some(-5))
            .expect("set blocker row start");
        tree.set_grid_row_end(blocker, Some(-4))
            .expect("set blocker row end");
    } else {
        tree.set_grid_column_start(blocker, Some(-5))
            .expect("set blocker column start");
        tree.set_grid_column_end(blocker, Some(-4))
            .expect("set blocker column end");
        tree.set_grid_row_start(blocker, Some(1))
            .expect("set blocker row start");
    }
    tree.append_child(root, blocker)
        .expect("append leading implicit blocker");

    for (index, span) in [2, 2, 1].into_iter().enumerate() {
        let child = tree.create_default_measured_node(Size::new(7.0 + index as f32, 5.0));
        tree.set_display(child, Display::Block)
            .expect("set leading implicit grid child display");
        if is_column_flow {
            tree.set_grid_row_span(child, span)
                .expect("set leading implicit child row span");
        } else {
            tree.set_grid_column_span(child, span)
                .expect("set leading implicit child column span");
        }
        tree.append_child(root, child)
            .unwrap_or_else(|_| panic!("append leading implicit grid child {index}"));
    }

    (tree, root, Constraints::definite(60.0, 60.0))
}

#[cfg(feature = "native-standalone")]
fn grid_auto_placement_matrix_root(tree: &mut StandaloneTree, flow: GridAutoFlow) -> NodeId {
    let root = tree.create_default_node();
    tree.set_display(root, Display::Grid)
        .expect("set matrix root display");
    tree.set_width(root, Length::points(60.0))
        .expect("set matrix root width");
    tree.set_height(root, Length::points(60.0))
        .expect("set matrix root height");
    tree.set_grid_auto_flow(root, flow)
        .expect("set matrix root auto flow");
    tree.set_grid_template_columns(
        root,
        [
            Length::points(10.0),
            Length::points(10.0),
            Length::points(10.0),
        ],
    )
    .expect("set matrix root columns");
    tree.set_grid_template_rows(
        root,
        [
            Length::points(10.0),
            Length::points(10.0),
            Length::points(10.0),
        ],
    )
    .expect("set matrix root rows");
    tree.set_grid_auto_columns(root, [Length::points(10.0)])
        .expect("set matrix root auto columns");
    tree.set_grid_auto_columns_max(root, [Length::points(10.0)])
        .expect("set matrix root auto column max tracks");
    tree.set_grid_auto_rows(root, [Length::points(10.0)])
        .expect("set matrix root auto rows");
    tree.set_grid_auto_rows_max(root, [Length::points(10.0)])
        .expect("set matrix root auto row max tracks");
    tree.set_justify_items(root, JustifyItems::Start)
        .expect("set matrix root justify items");
    tree.set_align_items(root, AlignItems::FlexStart)
        .expect("set matrix root align items");
    root
}

#[cfg(feature = "native-standalone")]
fn relative_dependencies_and_stretch_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_width(root, Length::points(140.0))
        .expect("set root width");
    tree.set_height(root, Length::points(96.0))
        .expect("set root height");

    let centered = tree.create_default_measured_node(Size::new(20.0, 10.0));
    tree.set_relative_center(centered, RelativeCenter::Both)
        .expect("set centered child relative center");

    let parent_aligned = tree.create_default_measured_node(Size::new(22.0, 14.0));
    tree.set_relative_id(parent_aligned, 20)
        .expect("set parent-aligned relative id");
    tree.set_relative_align_right(parent_aligned, RELATIVE_ALIGN_PARENT)
        .expect("set parent-aligned right edge");
    tree.set_relative_align_bottom(parent_aligned, RELATIVE_ALIGN_PARENT)
        .expect("set parent-aligned bottom edge");

    let before = tree.create_default_measured_node(Size::new(11.0, 6.0));
    tree.set_relative_left_of(before, 20)
        .expect("set before left-of dependency");
    tree.set_relative_top_of(before, 20)
        .expect("set before top-of dependency");

    let sibling_aligned = tree.create_default_measured_node(Size::new(7.0, 5.0));
    tree.set_relative_align_left(sibling_aligned, 20)
        .expect("set sibling-aligned left edge");
    tree.set_relative_align_bottom(sibling_aligned, 20)
        .expect("set sibling-aligned bottom edge");

    let left_anchor = tree.create_default_measured_node(Size::new(20.0, 10.0));
    tree.set_relative_id(left_anchor, 40)
        .expect("set left anchor id");
    tree.set_relative_align_left(left_anchor, RELATIVE_ALIGN_PARENT)
        .expect("set left anchor parent alignment");

    let right_anchor = tree.create_default_measured_node(Size::new(24.0, 10.0));
    tree.set_relative_id(right_anchor, 41)
        .expect("set right anchor id");
    tree.set_relative_align_right(right_anchor, RELATIVE_ALIGN_PARENT)
        .expect("set right anchor parent alignment");

    let stretched = tree.create_default_node();
    tree.set_display(stretched, Display::Block)
        .expect("set stretched display");
    tree.set_height(stretched, Length::points(8.0))
        .expect("set stretched height");
    tree.set_relative_right_of(stretched, 40)
        .expect("set stretched start dependency");
    tree.set_relative_left_of(stretched, 41)
        .expect("set stretched end dependency");
    tree.set_relative_align_top(stretched, RELATIVE_ALIGN_PARENT)
        .expect("set stretched top alignment");
    tree.set_margin(stretched, StandaloneEdge::Horizontal, Length::points(5.0))
        .expect("set stretched horizontal margin");

    tree.append_child(root, centered).expect("append centered");
    tree.append_child(root, before).expect("append before");
    tree.append_child(root, sibling_aligned)
        .expect("append sibling-aligned");
    tree.append_child(root, stretched)
        .expect("append stretched");
    tree.append_child(root, right_anchor)
        .expect("append right anchor");
    tree.append_child(root, left_anchor)
        .expect("append left anchor");
    tree.append_child(root, parent_aligned)
        .expect("append parent-aligned");

    (tree, root, Constraints::indefinite())
}

