#[cfg(feature = "native-standalone")]
fn relative_duplicate_ids_and_display_none_anchor_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_width(root, Length::points(120.0))
        .expect("set root width");
    tree.set_height(root, Length::points(80.0))
        .expect("set root height");

    let first_anchor = tree.create_default_measured_node(Size::new(60.0, 40.0));
    tree.set_relative_id(first_anchor, 10)
        .expect("set first anchor id");
    tree.set_relative_align_right(first_anchor, RELATIVE_ALIGN_PARENT)
        .expect("set first anchor right alignment");
    tree.set_relative_align_bottom(first_anchor, RELATIVE_ALIGN_PARENT)
        .expect("set first anchor bottom alignment");

    let position_follower = tree.create_default_measured_node(Size::new(5.0, 7.0));
    tree.set_relative_right_of(position_follower, 10)
        .expect("set position follower right-of dependency");
    tree.set_relative_bottom_of(position_follower, 10)
        .expect("set position follower bottom-of dependency");

    let edge_follower = tree.create_default_measured_node(Size::new(6.0, 7.0));
    tree.set_relative_align_left(edge_follower, 10)
        .expect("set edge follower left alignment");
    tree.set_relative_align_bottom(edge_follower, 10)
        .expect("set edge follower bottom alignment");

    let last_visible_anchor = tree.create_default_measured_node(Size::new(20.0, 10.0));
    tree.set_relative_id(last_visible_anchor, 10)
        .expect("set last visible anchor id");

    let hidden_anchor = tree.create_default_node();
    tree.set_display(hidden_anchor, Display::None)
        .expect("set hidden anchor display");
    tree.set_relative_id(hidden_anchor, 10)
        .expect("set hidden anchor id");
    tree.set_width(hidden_anchor, Length::points(80.0))
        .expect("set hidden anchor width");
    tree.set_height(hidden_anchor, Length::points(40.0))
        .expect("set hidden anchor height");

    tree.append_child(root, first_anchor)
        .expect("append first anchor");
    tree.append_child(root, position_follower)
        .expect("append position follower");
    tree.append_child(root, edge_follower)
        .expect("append edge follower");
    tree.append_child(root, last_visible_anchor)
        .expect("append last visible anchor");
    tree.append_child(root, hidden_anchor)
        .expect("append hidden anchor");

    (tree, root, Constraints::definite(120.0, 80.0))
}

