#[cfg(feature = "native-standalone")]
fn root_relative_fit_content_wrap_content_tree(
) -> (&'static str, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_box_sizing(root, BoxSizing::ContentBox)
        .expect("set root box sizing");
    tree.set_width(
        root,
        Length::fit_content(Some(BaseLength::fixed_and_percent(10.0, 50.0))),
    )
    .expect("set root width");
    tree.set_height(
        root,
        Length::fit_content(Some(BaseLength::fixed_and_percent(5.0, 25.0))),
    )
    .expect("set root height");

    let child = tree.create_default_measured_node(Size::new(140.0, 70.0));
    tree.set_box_sizing(child, BoxSizing::ContentBox)
        .expect("set child box sizing");
    tree.append_child(root, child).expect("append child");

    (
        "root relative fit-content uses wrap-content size",
        tree,
        root,
        Constraints::definite(200.0, 100.0),
    )
}

#[cfg(feature = "native-standalone")]
fn child_relative_fit_content_wrap_content_tree(
) -> (&'static str, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Block)
        .expect("set root display");
    tree.set_box_sizing(root, BoxSizing::ContentBox)
        .expect("set root box sizing");
    tree.set_width(root, Length::points(200.0))
        .expect("set root width");
    tree.set_height(root, Length::points(100.0))
        .expect("set root height");

    let relative = tree.create_default_node();
    tree.set_display(relative, Display::Relative)
        .expect("set relative display");
    tree.set_box_sizing(relative, BoxSizing::ContentBox)
        .expect("set relative box sizing");
    tree.set_width(
        relative,
        Length::fit_content(Some(BaseLength::fixed_and_percent(10.0, 50.0))),
    )
    .expect("set relative width");
    tree.set_height(
        relative,
        Length::fit_content(Some(BaseLength::fixed_and_percent(5.0, 25.0))),
    )
    .expect("set relative height");

    let child = tree.create_default_measured_node(Size::new(140.0, 70.0));
    tree.set_box_sizing(child, BoxSizing::ContentBox)
        .expect("set child box sizing");

    tree.append_child(root, relative).expect("append relative");
    tree.append_child(relative, child).expect("append child");

    (
        "child relative fit-content uses wrap-content size",
        tree,
        root,
        Constraints::definite(200.0, 100.0),
    )
}

