#[cfg(feature = "native-standalone")]
fn relative_padding_border_content_origin_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_width(root, Length::points(100.0))
        .expect("set root width");
    tree.set_height(root, Length::points(80.0))
        .expect("set root height");
    tree.set_padding(root, StandaloneEdge::Left, Length::points(3.0))
        .expect("set root left padding");
    tree.set_padding(root, StandaloneEdge::Right, Length::points(7.0))
        .expect("set root right padding");
    tree.set_padding(root, StandaloneEdge::Top, Length::points(5.0))
        .expect("set root top padding");
    tree.set_padding(root, StandaloneEdge::Bottom, Length::points(11.0))
        .expect("set root bottom padding");
    tree.set_border(root, StandaloneEdge::Left, 2.0)
        .expect("set root left border");
    tree.set_border(root, StandaloneEdge::Right, 1.0)
        .expect("set root right border");
    tree.set_border(root, StandaloneEdge::Top, 4.0)
        .expect("set root top border");
    tree.set_border(root, StandaloneEdge::Bottom, 6.0)
        .expect("set root bottom border");

    let anchor = fixed_standalone_block(&mut tree, 20.0, 10.0);
    tree.set_relative_id(anchor, 10)
        .expect("set anchor relative id");

    let parent_end = fixed_standalone_block(&mut tree, 10.0, 8.0);
    tree.set_relative_align_right(parent_end, RELATIVE_ALIGN_PARENT)
        .expect("set parent-end right alignment");
    tree.set_relative_align_bottom(parent_end, RELATIVE_ALIGN_PARENT)
        .expect("set parent-end bottom alignment");

    let centered = fixed_standalone_block(&mut tree, 20.0, 10.0);
    tree.set_relative_center(centered, RelativeCenter::Both)
        .expect("set centered relative center");

    let sibling_after = fixed_standalone_block(&mut tree, 6.0, 4.0);
    tree.set_relative_right_of(sibling_after, 10)
        .expect("set sibling-after right-of");
    tree.set_relative_bottom_of(sibling_after, 10)
        .expect("set sibling-after bottom-of");

    for child in [anchor, parent_end, centered, sibling_after] {
        tree.append_child(root, child)
            .expect("append relative child");
    }

    (tree, root, Constraints::indefinite())
}

#[cfg(feature = "native-standalone")]
#[derive(Clone, Copy)]
enum RelativeSiblingEdgeCase {
    RightOf,
    LeftOf,
    AlignLeft,
    AlignRight,
    BottomOf,
    TopOf,
    AlignTop,
    AlignBottom,
    AlignLeftToParentRight,
    AlignTopToParentBottom,
}

#[cfg(feature = "native-standalone")]
impl RelativeSiblingEdgeCase {
    const CASES: [Self; 10] = [
        Self::RightOf,
        Self::LeftOf,
        Self::AlignLeft,
        Self::AlignRight,
        Self::BottomOf,
        Self::TopOf,
        Self::AlignTop,
        Self::AlignBottom,
        Self::AlignLeftToParentRight,
        Self::AlignTopToParentBottom,
    ];

    fn name(self) -> &'static str {
        match self {
            Self::RightOf => "relative sibling right-of",
            Self::LeftOf => "relative sibling left-of",
            Self::AlignLeft => "relative sibling align-left",
            Self::AlignRight => "relative sibling align-right",
            Self::BottomOf => "relative sibling bottom-of",
            Self::TopOf => "relative sibling top-of",
            Self::AlignTop => "relative sibling align-top",
            Self::AlignBottom => "relative sibling align-bottom",
            Self::AlignLeftToParentRight => "relative sibling align-left to parent-right",
            Self::AlignTopToParentBottom => "relative sibling align-top to parent-bottom",
        }
    }
}

#[cfg(feature = "native-standalone")]
fn relative_sibling_edge_tree(
    case: RelativeSiblingEdgeCase,
) -> (&'static str, StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = tree.create_default_node();
    tree.set_display(root, Display::Relative)
        .expect("set root display");
    tree.set_width(root, Length::points(120.0))
        .expect("set root width");
    tree.set_height(root, Length::points(90.0))
        .expect("set root height");
    tree.set_padding(root, StandaloneEdge::Left, Length::points(3.0))
        .expect("set root left padding");
    tree.set_padding(root, StandaloneEdge::Right, Length::points(5.0))
        .expect("set root right padding");
    tree.set_padding(root, StandaloneEdge::Top, Length::points(7.0))
        .expect("set root top padding");
    tree.set_padding(root, StandaloneEdge::Bottom, Length::points(11.0))
        .expect("set root bottom padding");

    let anchor = fixed_standalone_block(&mut tree, 30.0, 20.0);
    tree.set_relative_id(anchor, 10)
        .expect("set anchor relative id");
    tree.set_relative_align_left(anchor, RELATIVE_ALIGN_PARENT)
        .expect("set anchor left alignment");
    tree.set_relative_align_top(anchor, RELATIVE_ALIGN_PARENT)
        .expect("set anchor top alignment");
    tree.set_margin(anchor, StandaloneEdge::Left, Length::points(2.0))
        .expect("set anchor left margin");
    tree.set_margin(anchor, StandaloneEdge::Right, Length::points(4.0))
        .expect("set anchor right margin");
    tree.set_margin(anchor, StandaloneEdge::Top, Length::points(3.0))
        .expect("set anchor top margin");
    tree.set_margin(anchor, StandaloneEdge::Bottom, Length::points(5.0))
        .expect("set anchor bottom margin");

    let dependent = fixed_standalone_block(&mut tree, 10.0, 8.0);
    tree.set_margin(dependent, StandaloneEdge::Left, Length::points(1.0))
        .expect("set dependent left margin");
    tree.set_margin(dependent, StandaloneEdge::Right, Length::points(2.0))
        .expect("set dependent right margin");
    tree.set_margin(dependent, StandaloneEdge::Top, Length::points(3.0))
        .expect("set dependent top margin");
    tree.set_margin(dependent, StandaloneEdge::Bottom, Length::points(4.0))
        .expect("set dependent bottom margin");
    set_relative_sibling_edge_case(&mut tree, dependent, case);

    tree.append_child(root, dependent)
        .expect("append dependent");
    tree.append_child(root, anchor).expect("append anchor");

    (case.name(), tree, root, Constraints::indefinite())
}

#[cfg(feature = "native-standalone")]
fn set_relative_sibling_edge_case(
    tree: &mut StandaloneTree,
    node: NodeId,
    case: RelativeSiblingEdgeCase,
) {
    match case {
        RelativeSiblingEdgeCase::RightOf => tree
            .set_relative_right_of(node, 10)
            .expect("set right-of dependency"),
        RelativeSiblingEdgeCase::LeftOf => tree
            .set_relative_left_of(node, 10)
            .expect("set left-of dependency"),
        RelativeSiblingEdgeCase::AlignLeft => tree
            .set_relative_align_left(node, 10)
            .expect("set align-left dependency"),
        RelativeSiblingEdgeCase::AlignRight => tree
            .set_relative_align_right(node, 10)
            .expect("set align-right dependency"),
        RelativeSiblingEdgeCase::BottomOf => tree
            .set_relative_bottom_of(node, 10)
            .expect("set bottom-of dependency"),
        RelativeSiblingEdgeCase::TopOf => tree
            .set_relative_top_of(node, 10)
            .expect("set top-of dependency"),
        RelativeSiblingEdgeCase::AlignTop => tree
            .set_relative_align_top(node, 10)
            .expect("set align-top dependency"),
        RelativeSiblingEdgeCase::AlignBottom => tree
            .set_relative_align_bottom(node, 10)
            .expect("set align-bottom dependency"),
        RelativeSiblingEdgeCase::AlignLeftToParentRight => {
            tree.set_relative_align_left(node, 10)
                .expect("set align-left dependency");
            tree.set_relative_align_right(node, RELATIVE_ALIGN_PARENT)
                .expect("set parent-right dependency");
        }
        RelativeSiblingEdgeCase::AlignTopToParentBottom => {
            tree.set_relative_align_top(node, 10)
                .expect("set align-top dependency");
            tree.set_relative_align_bottom(node, RELATIVE_ALIGN_PARENT)
                .expect("set parent-bottom dependency");
        }
    }
}

