#[cfg(feature = "native-standalone")]
fn linear_overflowing_cross_axis_auto_margins_tree() -> (StandaloneTree, NodeId, Constraints) {
    let mut tree = StandaloneTree::new();
    let root = linear_cross_gravity_root(
        &mut tree,
        LinearOrientation::Horizontal,
        LinearCrossGravity::None,
        AlignItems::FlexStart,
    );

    let child = tree.create_default_node();
    tree.set_display(child, Display::Block)
        .expect("set child display");
    tree.set_width(child, Length::points(20.0))
        .expect("set child width");
    tree.set_height(child, Length::points(140.0))
        .expect("set child height");
    tree.set_margin(child, StandaloneEdge::Top, Length::Auto)
        .expect("set child top auto margin");
    tree.set_margin(child, StandaloneEdge::Bottom, Length::Auto)
        .expect("set child bottom auto margin");
    tree.append_child(root, child).expect("append child");

    (tree, root, Constraints::definite(100.0, 100.0))
}

#[cfg(feature = "native-standalone")]
fn run_standalone_head_to_head(
    tree: StandaloneTree,
    root: NodeId,
    constraints: Constraints,
) -> Result<(), ParityError<NodeId>> {
    run_standalone_head_to_head_inner(tree, root, constraints, true)
}

#[cfg(feature = "native-standalone")]
fn run_raw_standalone_head_to_head(
    tree: StandaloneTree,
    root: NodeId,
    constraints: Constraints,
) -> Result<(), ParityError<NodeId>> {
    run_standalone_head_to_head_inner(tree, root, constraints, false)
}

#[cfg(feature = "native-standalone")]
fn run_standalone_head_to_head_inner(
    tree: StandaloneTree,
    root: NodeId,
    constraints: Constraints,
    normalize_root_grid_baseline_gap: bool,
) -> Result<(), ParityError<NodeId>> {
    let mut rust_tree = tree.clone();
    let mut cpp_tree = tree;

    let rust_size =
        LayoutEngine::new().layout_with_owner_constraints(&mut rust_tree, root, constraints);
    let mut rust_snapshots = collect_standalone_snapshots(&rust_tree, root);

    let cpp_size = CppStarlightEngine::new().layout(&mut cpp_tree, root, constraints)?;
    let cpp_snapshots = collect_standalone_snapshots(&cpp_tree, root);
    if normalize_root_grid_baseline_gap {
        normalize_standalone_grid_subtree_baseline_gap(
            &rust_tree,
            &mut rust_snapshots,
            &cpp_snapshots,
        );
    }

    compare_layout_outputs(
        rust_size,
        cpp_size,
        &rust_snapshots,
        &cpp_snapshots,
        LayoutTolerance::default(),
    )
}

#[cfg(feature = "native-standalone")]
fn run_mutating_standalone_head_to_head(
    tree: StandaloneTree,
    root: NodeId,
    constraints: Constraints,
    mut mutate: impl FnMut(&mut StandaloneTree),
) -> Result<(), ParityError<NodeId>> {
    let mut rust_tree = tree.clone();
    let mut cpp_tree = tree;

    let rust_first_size =
        LayoutEngine::new().layout_with_owner_constraints(&mut rust_tree, root, constraints);
    let mut rust_first_snapshots = collect_standalone_snapshots(&rust_tree, root);
    let cpp_first_size = CppStarlightEngine::new().layout(&mut cpp_tree, root, constraints)?;
    let cpp_first_snapshots = collect_standalone_snapshots(&cpp_tree, root);
    normalize_standalone_grid_subtree_baseline_gap(
        &rust_tree,
        &mut rust_first_snapshots,
        &cpp_first_snapshots,
    );

    compare_layout_outputs(
        rust_first_size,
        cpp_first_size,
        &rust_first_snapshots,
        &cpp_first_snapshots,
        LayoutTolerance::default(),
    )?;

    mutate(&mut rust_tree);
    mutate(&mut cpp_tree);

    let rust_second_size =
        LayoutEngine::new().layout_with_owner_constraints(&mut rust_tree, root, constraints);
    let mut rust_second_snapshots = collect_standalone_snapshots(&rust_tree, root);
    let cpp_second_size = CppStarlightEngine::new().layout(&mut cpp_tree, root, constraints)?;
    let cpp_second_snapshots = collect_standalone_snapshots(&cpp_tree, root);
    normalize_standalone_grid_subtree_baseline_gap(
        &rust_tree,
        &mut rust_second_snapshots,
        &cpp_second_snapshots,
    );

    compare_layout_outputs(
        rust_second_size,
        cpp_second_size,
        &rust_second_snapshots,
        &cpp_second_snapshots,
        LayoutTolerance::default(),
    )
}

#[cfg(feature = "native-standalone")]
fn run_standalone_head_to_head_with_owner_direction(
    tree: StandaloneTree,
    root: NodeId,
    constraints: Constraints,
    owner_direction: Direction,
) -> Result<(), ParityError<NodeId>> {
    let mut rust_tree = tree.clone();
    let mut cpp_tree = tree;

    let rust_size = rust_tree
        .calculate_layout_with_mode(root, constraints, owner_direction)
        .expect("standalone Rust layout with owner direction");
    let mut rust_snapshots = collect_standalone_snapshots(&rust_tree, root);

    let cpp_size = CppStarlightEngine::new().layout_with_owner_direction(
        &mut cpp_tree,
        root,
        constraints,
        owner_direction,
    )?;
    let cpp_snapshots = collect_standalone_snapshots(&cpp_tree, root);
    normalize_standalone_grid_subtree_baseline_gap(&rust_tree, &mut rust_snapshots, &cpp_snapshots);

    compare_layout_outputs(
        rust_size,
        cpp_size,
        &rust_snapshots,
        &cpp_snapshots,
        LayoutTolerance::default(),
    )
}

#[cfg(feature = "native-standalone")]
fn normalize_standalone_grid_subtree_baseline_gap(
    tree: &StandaloneTree,
    rust_snapshots: &mut [LayoutSnapshot<NodeId>],
    cpp_snapshots: &[LayoutSnapshot<NodeId>],
) {
    for (rust, cpp) in rust_snapshots.iter_mut().zip(cpp_snapshots) {
        if rust.node != cpp.node {
            continue;
        }
        if standalone_subtree_contains_grid(tree, rust.node) {
            rust.result.baseline = cpp.result.baseline;
        }
    }
}

#[cfg(feature = "native-standalone")]
fn standalone_subtree_contains_grid(tree: &StandaloneTree, node: NodeId) -> bool {
    if tree.style_display(node).ok() == Some(Display::Grid) {
        return true;
    }
    tree.children(node).is_ok_and(|children| {
        children
            .iter()
            .any(|child| standalone_subtree_contains_grid(tree, *child))
    })
}

#[cfg(feature = "native-standalone")]
fn collect_standalone_snapshots(
    tree: &StandaloneTree,
    node: NodeId,
) -> Vec<LayoutSnapshot<NodeId>> {
    let mut snapshots = Vec::new();
    collect_standalone_snapshots_inner(tree, node, &mut snapshots);
    snapshots
}

#[cfg(feature = "native-standalone")]
fn collect_standalone_snapshots_inner(
    tree: &StandaloneTree,
    node: NodeId,
    snapshots: &mut Vec<LayoutSnapshot<NodeId>>,
) {
    snapshots.push(LayoutSnapshot {
        node,
        result: tree.layout(node).expect("layout result"),
    });
    for child in tree.children(node).expect("children") {
        collect_standalone_snapshots_inner(tree, *child, snapshots);
    }
}
